dtsPropsFor.Button:
/** Visual style. `default` is the crest-orange fill; `outline` and `secondary` sit on paper; `ghost` is bare; `link` is inline text. */
variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
/** `default` is 40px tall, `sm` 36px, `lg` 44px; `icon` is a 40px square for a lone icon. `touch` is `default` with a 44px floor on a phone and nothing extra at `lg` — reach for it whenever the button is pressed standing on a pitch. */
size?: "default" | "sm" | "lg" | "icon" | "touch";
children?: React.ReactNode;
className?: string;
disabled?: boolean;
type?: "button" | "submit" | "reset";
onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Badge:
/** `default` is a pale crest tint; `success` green, `warning` amber, `muted` grey, `destructive` red tint, `outline` bordered text. */
variant?: "default" | "success" | "warning" | "muted" | "destructive" | "outline";
children?: React.ReactNode;
className?: string;

dtsPropsFor.Card:
/** Compose with CardHeader, CardTitle, CardDescription and CardContent. Paper-white surface, 1px border, 12px radius. */
