children?: React.ReactNode;
className?: string;

dtsPropsFor.CardDescription:
/** Muted 14px line under the title. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.CardContent:
/** Body area, 24px side padding, no top padding (CardHeader supplies it). */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Input:
