dtsPropsFor.Avatar:
/** Full name; initials are drawn when there is no photo. */
name: string;
/** A photo URL; omit to show initials. */
photoUrl?: string | null;
/** sm 32px · md 36px · lg 48px · xl 80px. */
size?: "sm" | "md" | "lg" | "xl";
