dtsPropsFor.PlayerToken:
/** Player name; initials are drawn when there is no photo. */
name: string;
photoUrl?: string | null;
/** Size the token with h-/w- classes; it has no default size. */
className?: string;
/** Drawn as a small badge on the token. */
shirtNumber?: number | null;

dtsPropsFor.TeamPicker:
id: string;
/** Form field name; repeated once per team when `multiple`. */
name: string;
/** Every team the reader may choose from; filtered in the browser as they type. */
teams: { id: string; name: string; ageGroup: string | null }[];
label?: string;
placeholder?: string;
/** Helper line under the field. */
help?: string;
required?: boolean;
/** Allow several teams, shown as chips. */
multiple?: boolean;

dtsPropsFor.SubmitButton:
/** Visible label. */
children?: React.ReactNode;
/** Screen-reader text while the surrounding form's action is pending. */
pendingLabel?: string;
variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
size?: "default" | "sm" | "lg" | "icon";
className?: string;
disabled?: boolean;

dtsPropsFor.PageHeader:
/** Page title, set in Oswald display caps. */
title: string;
subtitle?: string;
/** Right-aligned action, usually a Button. */
action?: React.ReactNode;
/** The way up: a chevron link above the title naming the parent list. */
back?: { href: string; label: string };
/** One-line header for screens whose content must fill a phone. */
compact?: boolean;

dtsPropsFor.EmptyState:
/** A rendered lucide element, never the component: `<Inbox className="h-5 w-5" aria-hidden />`. Drawn in a circle above the title. */
icon?: React.ReactNode;
/** What this screen would have shown — "No fixtures yet". */
title: string;
/** One sentence saying why it is empty, so an empty screen is never mistaken for a broken one. */
children?: React.ReactNode;
/** The single thing to do about it. */
action?: { href: string; label: string };

dtsPropsFor.LinkRow:
/** Where a click anywhere on the row goes. */
href: string;
className?: string;
/** The row's `<td>` cells. */
children: React.ReactNode;

dtsPropsFor.NavLink:
href: string;
/** Every href in the menu, so only the best match highlights. */
hrefs?: string[];
/** Indented sub-entry. */
child?: boolean;
/** Right-aligned count pill. */
badge?: string | number;
/** Right-aligned admin-only lock glyph. */
lock?: boolean;
/** Icon element followed by the label text. */
children: React.ReactNode;

dtsPropsFor.SectionHomeLink:
href: string;
label: string;
/** Pre-rendered icon element. */
icon?: React.ReactNode;

dtsPropsFor.FilterRail:
/** Show me / Whose groups; each option is a link with an optional swatch colour and live count. Drawn at lg and above only. */
groups: { title: string; options: { href: string; label: string; active: boolean; swatch?: string; count?: number | string }[] }[];
/** One thing worth knowing about this list. */
note?: { title: string; body: string };
footnote?: string;
/** The list itself, to the right of the rail. */
children: React.ReactNode;

dtsPropsFor.Sheet:
/** Draw it. A closed sheet renders nothing at all, so keep the caller mounted and flip this. */
open: boolean;
/** Called by Escape, by the close button and by a press on the dim. Keep the sheet's mode in your own state and clear it here; an inline arrow is fine, the sheet reads the latest one out of a ref. */
onClose: () => void;
/** The object the sheet is about — "Tuesday 18:00 · Pitch 2". It is the panel's accessible name, so write it as a name, not an instruction. */
title: string;
/** The second line under the title: what is being edited, in a few words. */
subtitle?: React.ReactNode;
/** `drawer` (bottom sheet on a phone, right-hand drawer at `lg`) for a panel you work IN — the winter-training shape and the default. `modal` for a choice you make and leave. `center` when it should float at every width, `top` for the command palette. */
side?: "drawer" | "modal" | "center" | "top";
/** Pixels: the drawer's width at `lg`, the widest the other shapes go. 460 suits a form; widen only for something tabular. */
width?: number;
/** One control beside the title — an Edit button, a Badge. A rendered element, never the component. */
headerAction?: React.ReactNode;
/** A row that stays put while the body scrolls: the sheet's own Cancel / Save. Leave it off and the buttons scroll away with the content. */
footer?: React.ReactNode;
/** Something the sheet asked the server is still in flight; it sets `aria-busy` on the panel. */
busy?: boolean;
/** The body. It already has `px-4 py-4 lg:px-5`; an edge-to-edge list cancels that with `-mx-4 -mt-4 lg:-mx-5`. */
children?: React.ReactNode;

dtsPropsFor.Popover:
/** Draw it. Closed renders nothing. */
open: boolean;
/** Called by Escape and by a press anywhere outside the panel. A press on the trigger itself is left alone, so the trigger can do its own toggling without reopening what it just shut. */
onClose: () => void;
/** The panel's accessible name — "Menu", "Members of this conversation". */
label: string;
/** Which edge of the trigger box the panel hangs from. Reach for `right` when the trigger sits at the right of the screen and a left-hung panel would run off it. */
anchor?: "left" | "right";
/** Pixels; the panel never grows wider than the screen less its margins. */
width?: number;
/** Dim the page behind it — only when the menu is a decision. A menu over a page you can still read does not. */
scrim?: boolean;
/** The menu's rows. The caller owns the trigger and the `relative` box the two share. */
children?: React.ReactNode;

dtsPropsFor.IconTile:
/** A rendered lucide element, never the component: `<Users className="h-4 w-4" aria-hidden />`. The caller sizes the glyph, the tile sizes the square. */
icon: React.ReactNode;
/** sm 32px for a list row · md 36px for a status bar · lg 40px for an empty state. */
size?: "sm" | "md" | "lg";
/** What the tile means: `primary` for a door, `muted` for something dormant, `success`/`warning`/`info` for a state. */
tone?: "primary" | "muted" | "success" | "warning" | "info";
/** `square` for a row or a fold; `round` for a person, or for the icon over an empty state. */
shape?: "square" | "round";
className?: string;

dtsPropsFor.FoldCard:
/** A rendered lucide element, never the component: `<CalendarOff className="h-4 w-4" aria-hidden />`. */
icon: React.ReactNode;
/** What is folded away — "Dates off", "Booker", "Emails sent". */
title: string;
/** What is inside, in a few words computed on the server: "Christmas, Half-term". Without it the closed row is not worth reading, and a fold nobody reads is a fold nobody opens. */
summary?: string;
/** Open on first paint. There is no controlled `open`: it is a native `<details>` and the browser owns the toggle, so a disclosure driven from outside is a different component. */
defaultOpen?: boolean;
className?: string;
/** The settings themselves. */
children?: React.ReactNode;

dtsPropsFor.ToggleChip:
/** Whether this chip is the chosen one; it becomes `aria-pressed`. Reach for this chip only when the toggle changes nothing but what is drawn — if the filter belongs in the URL, and it nearly always does, use `ToggleChipLink`. */
on: boolean;
/** The number riding on the right of the label. Zero is not drawn, because "Thursday 0" is noise. */
count?: number;
/** `md` settles to 34px at `lg`, `sm` to 30px for a dense strip. Both are a 44px thumb target on a phone. */
size?: "sm" | "md";
/** The label. */
children?: React.ReactNode;
className?: string;
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.ToggleChipLink:
/** Where the filtered view lives. This is the chip to reach for whenever a narrowed list should be shareable and Back should undo a tap. */
href: string;
/** Whether this chip is the view being shown; it becomes `aria-current="page"`. */
active: boolean;
/** The number riding on the right of the label; zero is not drawn. */
count?: number;
/** `md` settles to 34px at `lg`, `sm` to 30px. Both are a 44px thumb target on a phone. */
size?: "sm" | "md";
/** The label. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.ChipStrip:
/** The chips. On a phone they sit on one line that scrolls sideways instead of wrapping into a ladder, bleeding into the page's 16px padding so the last chip runs off the edge — which is how a phone says there is more this way. At `lg` the bleed is cancelled. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Callout:
/** What it means: `info` for a thing worth knowing about the list beside it, `success` for what the server just did, `warning` for "look at this soon", `danger` for something that failed. */
tone?: "info" | "success" | "warning" | "danger";
/** A bold first line, for when the body needs a heading to be read at all. */
title?: React.ReactNode;
/** A rendered lucide element, never the component: `<AlertCircle className="h-4 w-4" aria-hidden />`. */
icon?: React.ReactNode;
/** The sentence itself. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.StatTile:
/** The figure's name, in small muted type — "Outstanding", "Registered", "This season". */
label: React.ReactNode;
/** The figure. Oswald and `tabular-nums`, so a band of them lines up digit under digit and a number changing does not shuffle the layout. */
value: React.ReactNode;
/** The line under the figure — "3 over 60 days", "of £1,840 due". */
hint?: React.ReactNode;
/** Colour the figure by what it means. Leave it `default` unless the number is itself good or bad news. */
tone?: "default" | "success" | "warning" | "danger" | "info";
/** Makes the whole tile one press. Reach for it whenever the figure has a list behind it — every drill-down is a URL. */
href?: string;
/** A rendered lucide element, never the component: `<Receipt className="h-3.5 w-3.5" aria-hidden />`. */
icon?: React.ReactNode;
className?: string;

dtsPropsFor.StatRow:
/** The tiles: two across on a phone, four at `lg`. It is the facts band a screen opens with, above the fold and under the header. */
children?: React.ReactNode;
/** Say otherwise about the grid — `md:grid-cols-3 xl:grid-cols-6` for a hub with six tiles. The caller wins. */
className?: string;

dtsPropsFor.ActionBar:
/** A rendered lucide element, never the component: `<CalendarCheck2 className="h-4 w-4" aria-hidden />`. */
icon?: React.ReactNode;
/** The one sentence saying what this object needs next. Every makeover screen opens with it, above the fold. */
status: React.ReactNode;
/** The line under it: why, or what happens after the press. */
detail?: React.ReactNode;
/** What the sentence means, not decoration. `waiting` is "nothing moves until you press", `pending` while it is in flight, `done` the past tense after a press, `error` what went wrong. */
tone?: "idle" | "pending" | "waiting" | "done" | "error";
/** The ONE control the bar exists for — usually a single Button, disabled with a reason on it when there is nothing to do. */
action: React.ReactNode;
/** Drawn beneath the row inside the same surface: a footnote, or the named warnings a bulk action came back with. */
children?: React.ReactNode;
/** `form` makes the bar itself the `<form>`, so its button is a plain submit and `useActionState` can drive the whole bar. */
as?: "div" | "form";
/** With `as="form"`: the server action or `useActionState` dispatcher. It is not called `action` because that slot is already the button; hidden inputs ride inside `action`. */
formAction?: (formData: FormData) => void | Promise<void>;
className?: string;

dtsPropsFor.Eyebrow:
/** The tag. `p` by default because it is a signpost rather than a heading; use `h2` with an `id` when it really does name a landmark a screen reader should announce. */
as?: "p" | "h2" | "h3" | "span";
/** `muted` for a plain group label; `primary` or `accent` when the group is the one being shown. */
tone?: "muted" | "primary" | "accent";
/** The label — "Your teams", "Show me", "Tuesdays". */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Kbd:
/** The key, written the way it is printed on it: `⌘K`, `Esc`, `/`. Put it beside the thing the shortcut opens, so the shortcut is found by people who never read a help page. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Table:
/** A `<THead>` of `<TH>`s and a `<TBody>` of `<TR>`s of `<TD>`s, plus a `<colgroup>` when the columns need widths. All five parts are exported beside `Table`; `TH`, `TR` and `TD` have no entry of their own here only because a two-letter name reads to the extractor as an enum. `TH` is the column name (`text-right` for money, `w-10` for a tick column, a muted second line when the name needs qualifying), `TR` the row (it tints on hover; `opacity-60` when the row is on the books but not in play) and `TD` the cell (`whitespace-nowrap` for a date, `font-medium` for the one that names the row). There is no behaviour here on purpose — no sorting, no selection, no empty state; a list that wants those wants `DataListFrame`, which is built on these. */
children?: React.ReactNode;
/** The table does not scroll on its own: wrap it in `<div className="overflow-x-auto">` when it is wider than the page, because only the caller knows whether the page or the table should be the thing that moves sideways. */
className?: string;

dtsPropsFor.THead:
/** One `<tr>` of `<TH>`s — and a second `<tr>` beneath it when the columns carry filters. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.TBody:
/** The `<TR>`s; they are already separated by a hairline rule, so no row needs its own border. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.DataListFrame:
/** Every row the server sent, each with its `<td>`s ALREADY RENDERED in `cells` and its phone twin in `card`. The frame never looks inside them: a server page keeps rendering its own staff names and kick-off times and hands over only the chrome, so adopting it costs no queries. `haystack` is what the search box reads, already lower-cased; `facets` maps each column's `filterKey` to this row's value; `dim` fades a row that is on the books but not in play. */
items: { key: string; haystack: string; facets?: Record<string, string>; cells: React.ReactNode; card?: React.ReactNode; dim?: boolean }[];
/** The columns, in order. `weight` becomes a percentage width, `sub` is the small second line under the label, `filterKey` gives the column its own dropdown and `allLabel` names that dropdown's everything option ("All ages" reads better than "All"). */
columns: { key: string; label: string; sub?: string; weight?: number; align?: "left" | "right"; filterKey?: string; allLabel?: string }[];
/** The filter-as-you-type box, mirrored into `?<param>=`. It narrows rows the server ALREADY SENT, so leave it off a paginated list — otherwise it will tell somebody a member does not exist. */
search?: { param: string; placeholder: string; initial: string };
/** The caller's own filter pills above the box, usually a `ChipStrip` of `ToggleChipLink`s. */
chips?: React.ReactNode;
/** Tick mode. `bar` is handed the ticked keys and a way to clear them and returns the bulk bar drawn above the list; it is called only while something is ticked. It is a function, so `select` can only come from a client component. */
select?: { label: string; bar: (keys: string[], clear: () => void) => React.ReactNode };
/** Shown when there are no rows AT ALL, as opposed to none matching. `icon` is a rendered lucide element, never the component. */
empty: { title: string; body?: React.ReactNode; icon?: React.ReactNode; action?: { href: string; label: string } };
/** Shown instead when there are rows but the filters hide every one of them. */
noMatch?: string;
/** Server-rendered controls beside the search box — a "New team" button. */
actions?: React.ReactNode;
/** The quiet line under the table, right-aligned: "13 teams · 4 hidden". */
footerNote?: React.ReactNode;
/** The press in the footer for rows the page is holding back — "Show the other 6 teams". A server page gives it an `href`; a client caller may give it an `onShow` instead. */
showMore?: { label: string; href?: string; onShow?: () => void };
